// Geometry information for lower surfaces (left, bottom, front) for a cell
struct gkyl_gk_dg_surf_geom {
  double B3; // n^3 \cdot \vec{B}
  double normcurlbhat; // normal to face perp to direction 'd' dotted with curl(bhat)
  double bmag; // |B|
  struct gkyl_vec3 bhat; // Covariant components of bhat (b_i)
  double Jc; // J_c
};

// Geometry information for a single cell
struct gkyl_gk_dg_vol_geom {
  double bmag; // |B|
  double B3; // n^3 \cdot \vec{B}
  struct gkyl_vec3 dualcurlbhat; // duals dotted with curl(bhat)
};

// geometry information over a range of cells:
struct gkyl_gk_dg_geom {
  struct gkyl_range range; // range over which geometry is defined
  struct gkyl_range surf_quad_range; // range for indexing surface nodes
  struct gkyl_range vol_quad_range; // range for indexing volume nodes

  struct gkyl_array *surf_geom[GKYL_MAX_CDIM]; // surface geometry in dir 'd' in each cell
  struct gkyl_array *vol_geom; // cell geometry

  uint32_t flags;
  struct gkyl_ref_count ref_count;
  struct gkyl_gk_dg_geom *on_dev; // pointer to itself or device object
};

// Input for constructing geometry with mapc2p
struct gkyl_gk_dg_geom_inp {
  const struct gkyl_rect_grid *grid; // grid over which geometry needs to be defined
  struct gkyl_range *range; // range of grid: this needs to be extended grid
  bool skip_geometry_creation; // true if only allocation is needed (geom must be computed eleswhere)
  int nquad; // number of quadrature points in each direction
  evalf_t mapc2p; // mapping function: set mapc2p = 0 to use identity map
  void *ctx; // context for use in mapc2p
  bool use_gpu; // does this live on the GPU?
};

/**
 * Create a new DG geometry object from mapc2p. 
 *
 * @param inp Inputs for use in constructing geometry
 */
struct gkyl_gk_dg_geom *gkyl_gk_dg_geom_new(const struct gkyl_gk_dg_geom_inp *inp);

/**
 * Create a new DG geometry object from host object. 
 *
 * @param up_host geometry object on host
 * @param inp Inputs for use in constructing geometry
 * @param use_gpu whether to use gpu
 */
struct gkyl_gk_dg_geom *gkyl_gk_dg_geom_new_from_host(
  const struct gkyl_gk_dg_geom_inp *inp, struct gkyl_gk_dg_geom *up_host, bool use_gpu
);

struct gkyl_gk_dg_geom *gkyl_gk_dg_geom_cu_dev_new_from_host(
  const struct gkyl_gk_dg_geom_inp *inp, struct gkyl_gk_dg_geom *up_host
);

/**
 * Acquire pointer to geometry object. The pointer must be released
 * using gkyl_gk_dg_geom_release method.
 *
 * @param dgg Geometry to which a pointer is needed
 * @return Pointer to acquired geometry
 */
struct gkyl_gk_dg_geom *gkyl_gk_dg_geom_acquire(const struct gkyl_gk_dg_geom *dgg);

/**
 * Write out geometry data to file. The "fprefix" is the prefix of the
 * set of file names.
 *
 * @param dgg Geometry to which a pointer is needed
 * @param fname Name of output file to write
 */
void gkyl_gk_dg_geom_write(const struct gkyl_gk_dg_geom *dgg, const char *fprefix);

/**
 * Get pointer to geometry on the surface normal to 'd' given by idx
 * into the range over which the geometry was constructed. The
 * returned array needs to be further indexed to fetch the specific
 * struct at a quadrature point
 *
 * @param dgg DG geometry object
 * @param d Direction to which surface is perpendicular
 * @param idx Index into grid
 * @return Pointer to surface geometry at all quadrature nodes in cell @a idx
 */
GKYL_CU_DH static inline const struct gkyl_gk_dg_surf_geom *
gkyl_gk_dg_geom_get_surf(const struct gkyl_gk_dg_geom *dgg, int d, const int *idx)
{
  return (const struct gkyl_gk_dg_surf_geom *)gkyl_array_cfetch(
    dgg->surf_geom[d], gkyl_range_idx(&dgg->range, idx)
  );
}

/**
 * Get linear index into surface quadrature node corresponding to
 * multi-dimensional index @a idx.
 *
 * @param dgg DG geometry object
 * @param idx Index (ndim-1) of surface quadrature node
 * @return Linear index for indexing surface quadrature array
 */
GKYL_CU_DH static inline long
gkyl_gk_dg_geom_surf_quad_idx(const struct gkyl_gk_dg_geom *dgg, const int *idx)
{
  return gkyl_range_idx(&dgg->surf_quad_range, idx);
}

/**
 * Get pointer to geometry in cell given by idx into the range over
 * which the geometry was constructed. The returned array needs to be
 * further indexed to fetch the specific struct at a quadrature point
 *
 * @param dgg DG geometry object
 * @param idx Index into grid
 * @return Pointer to cell geometry at all quadrature nodes in cell @a idx
 */
GKYL_CU_DH static inline const struct gkyl_gk_dg_vol_geom *
gkyl_gk_dg_geom_get_vol(const struct gkyl_gk_dg_geom *dgg, const int *idx)
{
  return (const struct gkyl_gk_dg_vol_geom *)gkyl_array_cfetch(
    dgg->vol_geom, gkyl_range_idx(&dgg->range, idx)
  );
}

/**
 * Get linear index into volume quadrature node corresponding to
 * multi-dimensional index @a vidx.
 *
 * @param dgg DG geometry object
 * @param vidx Index of volume quadrature node
 * @return Linear index for indexing volume quadrature array
 */
GKYL_CU_DH static inline long
gkyl_gk_dg_geom_vol_quad_idx(const struct gkyl_gk_dg_geom *dgg, const int *vidx)
{
  return gkyl_range_idx(&dgg->vol_quad_range, vidx);
}

/**
 * Release geometry object.
 *
 * @param dgg Dg geometry object to release.

item.formatted_output:
  struct test_sheath_ctx proj_ctx = {
    .B0 = B0,
    .mass = mass,
    .upar = upar_distf,
    .vt = vt_distf,
    .z0 = z0,
    .sigmaz = sigmaz,
  };
  gkyl_proj_on_basis *projDistf = gkyl_proj_on_basis_inew(&(struct gkyl_proj_on_basis_inp){
    .grid = &grid,
    .basis = &basis_ho,
    .num_ret_vals = 1,
    .eval = eval_func_1x2v,
    .ctx = &proj_ctx,
  });
  gkyl_proj_on_basis_advance(projDistf, 0.0, &local, distf_ho);
  gkyl_array_copy(distf, distf_ho);

  // Initialize the electrostatic potential at MPE and WALL
  double dgnormc = pow(sqrt(2.0), cdim);
  struct gkyl_array *phi = mkarr(use_gpu, basis_conf.num_basis, local_conf_ext.volume);
  struct gkyl_array *phi_ho = use_gpu ? mkarr(false, phi->ncomp, phi->size) :
                                        gkyl_array_acquire(phi);
  gkyl_array_shiftc(phi_ho, phi_mpe * dgnormc, 0 * basis_conf.num_basis);
  gkyl_array_copy(phi, phi_ho);

  struct gkyl_array *phiw = mkarr(use_gpu, basis_conf.num_basis, local_conf_ext.volume);
  struct gkyl_array *phiw_ho = use_gpu ? mkarr(false, phiw->ncomp, phiw->size) :
                                         gkyl_array_acquire(phiw);
  gkyl_array_shiftc(phiw_ho, phi_wall * dgnormc, 0 * basis_conf.num_basis);
  gkyl_array_copy(phiw, phiw_ho);

  // Create the BC updater.
  struct gkyl_bc_sheath_gyrokinetic *bcsheath = gkyl_bc_sheath_gyrokinetic_new(
    dir, edge, basis, &skin_r, &ghost_r, gvm, cdim, 2. * charge / mass, use_gpu
  );

  // Advance the BC updater.
  gkyl_bc_sheath_gyrokinetic_advance(bcsheath, phi, phiw, distf, &local_conf);

  // Copy back to host.
  gkyl_array_copy(distf_ho, distf);

  // Check the result.
  check_function(phi_mpe, phi_wall, charge, mass, cdim, distf_ho, grid, ghost_r, edge);

  // Write out the distribution function after applying BC if requested.
  if (write_fields) {
    write_out_fields(
      cdim, vdim, edge, use_gpu, distf_ho, phi_ho, phiw_ho, grid_ext, local_ext, grid_conf,
      local_conf, &basis_ho, basis_conf
    );
  }

  // Clean up.
  gkyl_proj_on_basis_release(projDistf);
  gkyl_array_release(distf);
  gkyl_array_release(distf_ho);
  gkyl_array_release(phi);
  gkyl_array_release(phi_ho);
  gkyl_array_release(phiw);
  gkyl_array_release(phiw_ho);
  if (use_gpu) {
    gkyl_cart_modal_basis_release_cu(basis);
  } else {
    gkyl_cart_modal_basis_release(basis);
  }

  gkyl_velocity_map_release(gvm);
  gkyl_bc_sheath_gyrokinetic_release(bcsheath);
}

void
test_bc_sheath_gyrokinetic_2x2v(
  const int *cells, enum gkyl_edge_loc edge, double charge, double phi_mpe, bool write_fields,
  bool use_gpu
)
{
  /*
  This test applies the sheath BC to a Maxwellian distribution function on both upper and lower edges in the z direction,
  according to a potential drop between the magnetic presheath entrance and the wall.
  The following files are written out if requested:
  - "bc_sheath_2x2v_distf_in.gkyl": Input distribution function.
  - "bc_sheath_2x2v_phi_mpe.gkyl": Potential at the magnetic presheath entrance (constant everywhere).
  - "bc_sheath_2x2v_phi_wall.gkyl": Potential at the wall (constant everywhere).
  - "bc_sheath_2x2v_distf_out.gkyl": Distribution after the sheath BC has been applied (includes ghost cells).
  */

  double mass = 1.; // Species mass.
  double vt = 1.0; // Reference thermal speed (for grid extents).
  double B0 = 1.0; // Magnetic field magnitude.
  double upar_distf = 1.0 * vt; // Parallel flow speed in distribution function.
  double vt_distf = 1.5 * vt; // Thermal speed in distribution function.
  double phi_wall = 0.0; // Potential at wall.
  double x0 = 0.0; // x-center of distribution function
  double z0 = 0.2; // z-center of distribution function
  double sigmax = 0.5; // Width of distribution function in x.
  double sigmaz = 1.0; // Width of distribution function in z.

  int poly_order = 1;
  double lower[] = {0.0, -1.0, -5.0 * vt, 0.};
  double upper[] = {1.0, 1.0, 5.0 * vt, mass * (pow(5.0 * vt, 2)) / (2.0 * B0)};
  int vdim = 2;
  int ndim = sizeof(lower) / sizeof(lower[0]);
  int cdim = ndim - vdim;
  int dir = cdim - 1; // Always applied in the parallel direction.

  double lower_conf[cdim], upper_conf[cdim];
  int cells_conf[cdim];
  for (int d = 0; d < cdim; d++) {
    lower_conf[d] = lower[d];
    upper_conf[d] = upper[d];
    cells_conf[d] = cells[d];
  }
  double lower_vel[vdim], upper_vel[vdim];
  int cells_vel[vdim];
  for (int d = 0; d < vdim; d++) {
    lower_vel[d] = lower[cdim + d];
    upper_vel[d] = upper[cdim + d];
    cells_vel[d] = cells[cdim + d];
  }

  // Grid.
  struct gkyl_rect_grid grid;
  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);
  struct gkyl_rect_grid grid_conf;
  gkyl_rect_grid_init(&grid_conf, cdim, lower_conf, upper_conf, cells_conf);
  struct gkyl_rect_grid grid_vel;
  gkyl_rect_grid_init(&grid_vel, vdim, lower_vel, upper_vel, cells_vel);

  // Basis functions.
  struct gkyl_basis *basis;
  basis = use_gpu ? gkyl_cart_modal_gkhybrid_cu_dev_new(cdim, vdim) :
                    gkyl_cart_modal_gkhybrid_new(cdim, vdim);

  struct gkyl_basis basis_ho;
  gkyl_cart_modal_gkhybrid(&basis_ho, cdim, vdim);

  struct gkyl_basis basis_conf;
  gkyl_cart_modal_serendip(&basis_conf, cdim, poly_order);

  int ghost_conf[] = {1, 1, 1};
  struct gkyl_range local_conf, local_conf_ext; // local, local-ext position-space ranges
  gkyl_create_grid_ranges(&grid_conf, ghost_conf, &local_conf_ext, &local_conf);

  int ghost_vel[] = {0, 0};
  struct gkyl_range local_vel, local_vel_ext; // local, local-ext vel-space ranges
  gkyl_create_grid_ranges(&grid_vel, ghost_vel, &local_vel_ext, &local_vel);

  int ghost[GKYL_MAX_DIM];
  for (int d = 0; d < cdim; d++) {
    ghost[d] = ghost_conf[d];
  }
  for (int d = 0; d < vdim; d++) {
    ghost[cdim + d] = ghost_vel[d];
  }
  struct gkyl_range local, local_ext; // local, local-ext phase-space ranges
  gkyl_create_grid_ranges(&grid, ghost, &local_ext, &local);

  // Initialize velocity space mapping.
  struct gkyl_mapc2p_inp c2p_in = {};
  struct gkyl_velocity_map *gvm = gkyl_velocity_map_new(
    c2p_in, grid, grid_vel, local, local_ext, local_vel, local_vel_ext, use_gpu
  );

  // Extended grid for the distribution function, which includes ghost cells.
  double lower_ext[ndim], upper_ext[ndim];
  int cells_ext[ndim];
  for (int d = 0; d < ndim; d++) {
    double dx = (upper[d] - lower[d]) / cells[d];
    lower_ext[d] = lower[d] - dx * ghost[d];
    upper_ext[d] = upper[d] + dx * ghost[d];
    cells_ext[d] = cells[d] + 2 * ghost[d];
  }
  struct gkyl_rect_grid grid_ext;
  gkyl_rect_grid_init(&grid_ext, ndim, lower_ext, upper_ext, cells_ext);

  // Create the skin/ghost ranges.
  struct gkyl_range skin_r, ghost_r;
  gkyl_skin_ghost_ranges(&skin_r, &ghost_r, dir, edge, &local_ext, ghost);

  // Initialize the distribution.
  struct gkyl_array *distf = mkarr(use_gpu, basis_ho.num_basis, local_ext.volume);
  struct gkyl_array *distf_ho = use_gpu ? mkarr(false, distf->ncomp, distf->size) :
                                          gkyl_array_acquire(distf);
  struct test_sheath_ctx proj_ctx = {
    .B0 = B0,
    .mass = mass,
    .upar = upar_distf,
    .vt = vt_distf,
    .x0 = x0,
    .z0 = z0,
    .sigmax = sigmax,
    .sigmaz = sigmaz,
  };
  gkyl_proj_on_basis *projDistf = gkyl_proj_on_basis_inew(&(struct gkyl_proj_on_basis_inp){
    .grid = &grid,
    .basis = &basis_ho,
    .num_ret_vals = 1,
    .eval = eval_func_2x2v,
    .ctx = &proj_ctx,
  });
  gkyl_proj_on_basis_advance(projDistf, 0.0, &local, distf_ho);
  gkyl_array_copy(distf, distf_ho);

  // Initialize the electrostatic potential at MPE and WALL.
  double dgnormc = pow(sqrt(2.0), cdim);
  struct gkyl_array *phi = mkarr(use_gpu, basis_conf.num_basis, local_conf_ext.volume);
  struct gkyl_array *phi_ho = use_gpu ? mkarr(false, phi->ncomp, phi->size) :
                                        gkyl_array_acquire(phi);
  gkyl_array_shiftc(phi_ho, phi_mpe * dgnormc, 0 * basis_conf.num_basis);
  gkyl_array_copy(phi, phi_ho);

  struct gkyl_array *phiw = mkarr(use_gpu, basis_conf.num_basis, local_conf_ext.volume);
  struct gkyl_array *phiw_ho = use_gpu ? mkarr(false, phiw->ncomp, phiw->size) :
                                         gkyl_array_acquire(phiw);
  gkyl_array_shiftc(phiw_ho, phi_wall * dgnormc, 0 * basis_conf.num_basis);
  gkyl_array_copy(phiw, phiw_ho);

  // Create the BC updater.
  struct gkyl_bc_sheath_gyrokinetic *bcsheath = gkyl_bc_sheath_gyrokinetic_new(
    dir, edge, basis, &skin_r, &ghost_r, gvm, cdim, 2. * charge / mass, use_gpu
  );

  // Advance the BC updater.
  gkyl_bc_sheath_gyrokinetic_advance(bcsheath, phi, phiw, distf, &local_conf);

  // Copy back to host.
  gkyl_array_copy(distf_ho, distf);

  // Check the result.
  check_function(phi_mpe, phi_wall, charge, mass, cdim, distf_ho, grid, ghost_r, edge);

  // Write out the distribution function after applying BC if requested.
  if (write_fields) {
    write_out_fields(
      cdim, vdim, edge, use_gpu, distf_ho, phi_ho, phiw_ho, grid_ext, local_ext, grid_conf,
      local_conf, &basis_ho, basis_conf
    );
  }

  // Clean up.
  gkyl_proj_on_basis_release(projDistf);
  gkyl_array_release(distf);
  gkyl_array_release(distf_ho);
  gkyl_array_release(phi);
  gkyl_array_release(phi_ho);
  gkyl_array_release(phiw);
  gkyl_array_release(phiw_ho);
  if (use_gpu) {
    gkyl_cart_modal_basis_release_cu(basis);
  } else {
    gkyl_cart_modal_basis_release(basis);
  }

  gkyl_velocity_map_release(gvm);
  gkyl_bc_sheath_gyrokinetic_release(bcsheath);
}

void
test_bc_sheath_gyrokinetic_3x2v(
  const int *cells, enum gkyl_edge_loc edge, double charge, double phi_mpe, bool write_fields,
  bool use_gpu
)
{
  /*
  This test applies the sheath BC to a Maxwellian distribution function on both upper and lower edges in the z direction,
  according to a potential drop between the magnetic presheath entrance and the wall.
  The following files are written out if requested:
  - "bc_sheath_3x2v_distf_in.gkyl": Input distribution function.
  - "bc_sheath_3x2v_phi_mpe.gkyl": Potential at the magnetic presheath entrance (constant everywhere).
  - "bc_sheath_3x2v_phi_wall.gkyl": Potential at the wall (constant everywhere).
  - "bc_sheath_3x2v_distf_out.gkyl": Distribution after the sheath BC has been applied (includes ghost cells).
  */

  double mass = 1.; // Species mass.
  double vt = 1.0; // Reference thermal speed (for grid extents).
  double B0 = 1.0; // Magnetic field magnitude.
  double upar_distf = 1.0 * vt; // Parallel flow speed in distribution function.
  double vt_distf = 1.5 * vt; // Thermal speed in distribution function.
  double phi_wall = 0.0; // Potential at wall.
/* -*- c++ -*- */

extern "C" {
#include <gkyl_bc_sheath_gyrokinetic.h>
#include <gkyl_bc_sheath_gyrokinetic_priv.h>
}

// CUDA kernel to set device pointers to kernel that computes the reflected f.
__global__ static void
gkyl_bc_gksheath_set_cu_ker_ptrs(
  const struct gkyl_basis *basis, enum gkyl_edge_loc edge,
  struct gkyl_bc_sheath_gyrokinetic_kernels *kers
)
{
  int dim = basis->ndim;
  enum gkyl_basis_type b_type = basis->b_type;
  int poly_order = basis->poly_order;

  switch (b_type) {
    case GKYL_BASIS_MODAL_GKHYBRID:
    case GKYL_BASIS_MODAL_SERENDIPITY:
      kers->reflectedf = ser_sheath_reflect_list[edge].list[dim - 2].kernels[poly_order - 1];
      break;
    default:
      assert(false);
  }
};

void
gkyl_bc_gksheath_choose_reflectedf_kernel_cu(
  const struct gkyl_basis *basis, enum gkyl_edge_loc edge,
  struct gkyl_bc_sheath_gyrokinetic_kernels *kers
)
{
  gkyl_bc_gksheath_set_cu_ker_ptrs<<<1, 1>>>(basis, edge, kers);
}

__global__ static void
gkyl_bc_sheath_gyrokinetic_advance_cu_ker(
  int cdim, int dir, const struct gkyl_range skin_r, const struct gkyl_range ghost_r,
  const struct gkyl_range conf_r, const struct gkyl_range vel_r, const struct gkyl_basis *basis,
  const struct gkyl_array *vmap, double q2Dm, const struct gkyl_array *phi,
  const struct gkyl_array *phi_wall, struct gkyl_bc_sheath_gyrokinetic_kernels *kers,
  struct gkyl_array *distf
)
{
  int fidx[GKYL_MAX_DIM]; // Flipped index.
  int pidx[GKYL_MAX_DIM];
  int vidx[2];

  int pdim = skin_r.ndim;
  int vpar_dir = cdim;
  int uplo = skin_r.upper[vpar_dir] + skin_r.lower[vpar_dir];

  for (unsigned long linc = threadIdx.x + blockIdx.x * blockDim.x; linc < skin_r.volume;
       linc += blockDim.x * gridDim.x) {
    // inverse index from linc1 to idx
    // must use gkyl_sub_range_inv_idx so that linc1=0 maps to idx={1,1,...}
    // since update_range is a subrange

    gkyl_sub_range_inv_idx(&skin_r, linc, pidx);

    gkyl_copy_int_arr(pdim, pidx, fidx);
    fidx[vpar_dir] = uplo - pidx[vpar_dir];
    // Turn this skin fidx into a ghost fidx.
    fidx[dir] = ghost_r.lower[dir];

    long skin_loc = gkyl_range_idx(&skin_r, pidx);
    long ghost_loc = gkyl_range_idx(&ghost_r, fidx);

    const double *inp = (const double *)gkyl_array_cfetch(distf, skin_loc);
    double *out = (double *)gkyl_array_fetch(distf, ghost_loc);

    for (int d = cdim; d < pdim; d++) {
      vidx[d - cdim] = pidx[d];
    }
    long conf_loc = gkyl_range_idx(&conf_r, pidx);
    long vel_loc = gkyl_range_idx(&vel_r, vidx);

    const double *phi_p = (const double *)gkyl_array_cfetch(phi, conf_loc);
    const double *phi_wall_p = (const double *)gkyl_array_cfetch(phi_wall, conf_loc);
    const double *vmap_p = (const double *)gkyl_array_cfetch(vmap, vel_loc);

    // Calculate reflected distribution function fhat.
    // note: reflected distribution can be
    // 1) fhat=0 (no reflection, i.e. absorb),
    // 2) fhat=f (full reflection)
    // 3) fhat=c*f (partial reflection)
    double fhat[112]; // MF 2022/08/24: hardcoded to number of DG coeffs in 3x2v p2 for now.
    kers->reflectedf(vmap_p, q2Dm, phi_p, phi_wall_p, inp, fhat);

    // Reflect fhat into skin cells.
    bc_gksheath_reflect(dir, basis, cdim, out, fhat);
  }
}

void
gkyl_bc_sheath_gyrokinetic_advance_cu(
  const struct gkyl_bc_sheath_gyrokinetic *up, const struct gkyl_array *phi,
  const struct gkyl_array *phi_wall, struct gkyl_array *distf, const struct gkyl_range *conf_r
)
{
  if (up->skin_r->volume > 0) {
    int nblocks = up->skin_r->nblocks, nthreads = up->skin_r->nthreads;

    gkyl_bc_sheath_gyrokinetic_advance_cu_ker<<<nblocks, nthreads>>>(
      up->cdim, up->dir, *up->skin_r, *up->ghost_r, *conf_r, up->vel_map->local_vel, up->basis,
      up->vel_map->vmap->on_dev, up->q2Dm, phi->on_dev, phi_wall->on_dev, up->kernels_cu,
      distf->on_dev
    );
  }
}
