   173	void
   174	gkyl_gk_dg_geom_populate_surf(
   175	  struct gkyl_dg_geom *dg_geom, struct gkyl_gk_dg_geom *gk_dg_geom, struct gk_geometry *gk_geom
   176	)
   177	{
   178	  int ndim = gk_geom->grid.ndim;
   179	  // Populate surface nodes
   180	  for (int dir = 0; dir < ndim; dir++) {
   181	    struct gkyl_range local_ext_in_dir;
   182	    int lower[3] = {gk_geom->local.lower[0], gk_geom->local.lower[1], gk_geom->local.lower[2]};
   183	    int upper[3] = {gk_geom->local.upper[0], gk_geom->local.upper[1], gk_geom->local.upper[2]};
   184	    upper[dir] += 1;
   185	    gkyl_sub_range_init(&local_ext_in_dir, &gk_geom->local_ext, lower, upper);
   186	
   187	    struct gkyl_range_iter iter;
   188	    gkyl_range_iter_init(&iter, &local_ext_in_dir);
   189	    while (gkyl_range_iter_next(&iter)) {
   190	      long loc = gkyl_range_idx(&local_ext_in_dir, iter.idx);
   191	      struct gkyl_dg_surf_geom *dgs = gkyl_array_fetch(dg_geom->surf_geom[dir], loc);
   192	      struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_array_fetch(gk_dg_geom->surf_geom[dir], loc);
   193	
   194	      struct gkyl_range_iter qsiter;
   195	      gkyl_range_iter_init(&qsiter, &dg_geom->surf_quad_range);
   196	      int global_nodal_idx[ndim];
   197	      while (gkyl_range_iter_next(&qsiter)) {
   198	        int count = 0;
   199	        for (int d = 0; d < ndim; ++d) {
   200	          global_nodal_idx[d] = d == dir ?
   201	                                  iter.idx[d] - gk_geom->local.lower[d] :
   202	                                  (iter.idx[d] - gk_geom->local.lower[d]) * 2 + qsiter.idx[count];
   203	          if (d != dir) {
   204	            count += 1;
   205	          }
   206	        }
   207	        long qsloc = gkyl_range_idx(&dg_geom->surf_quad_range, qsiter.idx);
   208	        long global_loc = gkyl_range_idx(&gk_geom->nrange_surf[dir], global_nodal_idx);
   209	
   210	        // set lenr
   211	        const double *global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].lenr_nodal, global_loc);
   212	        dgs[qsloc].area_elem = global_val[0];
   213	
   214	        // set normals
   215	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].normals_nodal, global_loc);
   216	        dgs[qsloc].norm.x[0] = global_val[dir * 3 + 0];
   217	        dgs[qsloc].norm.x[1] = global_val[dir * 3 + 1];
   218	        dgs[qsloc].norm.x[2] = global_val[dir * 3 + 2];
   219	
   220	        // set e3hat \dot B = B^3/sqrt(g_33}
   221	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].B3_nodal, global_loc);
   222	        gkdgs[qsloc].B3 = global_val[0];
   223	        // set n \dot curl(bhat)
   224	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].normcurlbhat_nodal, global_loc);
   225	        gkdgs[qsloc].normcurlbhat = global_val[0];
   226	
   227	        // set |B|
   228	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].bmag_nodal, global_loc);
   229	        gkdgs[qsloc].bmag = global_val[0];
   230	
   231	        // set Jacobgeo
   232	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].jacobgeo_nodal, global_loc);
   233	        gkdgs[qsloc].Jc = global_val[0];
   234	
   235	        // set bhat
   236	        global_val = gkyl_array_cfetch(gk_geom->geo_surf[dir].b_i_nodal, global_loc);
   237	        gkdgs[qsloc].bhat.x[0] = global_val[0];
   238	        gkdgs[qsloc].bhat.x[1] = global_val[1];
   239	        gkdgs[qsloc].bhat.x[2] = global_val[2];
   240	      }
   241	    }
   242	  }
   243	}


